        callbackUrl ||
        callbackUrl +
            (callbackUrl.replace(/^https?:\/\//i, '').match(/\//) ? '' : '/') +
            (callbackUrl.match(/\?/) ? '&' : '?') +
            'topic=' +
            encodeURIComponent(topic) +
            '&hub=' +
            encodeURIComponent(hub)
    // ...
